-- GallerySyncRepository.libraryAsset.getBackfill
select
  "asset"."id",
  "asset"."ownerId",
  "asset"."originalFileName",
  "asset"."thumbhash",
  "asset"."checksum",
  "asset"."fileCreatedAt",
  "asset"."fileModifiedAt",
  "asset"."createdAt",
  "asset"."localDateTime",
  "asset"."type",
  "asset"."deletedAt",
  "asset"."visibility",
  coalesce(
    (
      select
        "asset_video_trim"."duration"
      from
        "asset_video_trim"
      where
        "asset_video_trim"."assetId" = "asset"."id"
    ),
    "asset"."duration"
  ) as "duration",
  "asset"."livePhotoVideoId",
  "asset"."stackId",
  "asset"."libraryId",
  "asset"."width",
  "asset"."height",
  "asset"."isEdited",
  exists (
    select
      1 as "exists"
    from
      "asset_favorite"
    where
      "asset_favorite"."assetId" = "asset"."id"
      and "asset_favorite"."userId" = $1::uuid
  ) as "isFavorite",
  "asset"."updateId"
from
  "asset" as "asset"
where
  "asset"."updateId" < $2
  and "asset"."updateId" <= $3
  and "asset"."updateId" > $4
  and "asset"."libraryId" = $5
  and (
    "asset"."ownerId" = $6
    or (
      "asset"."visibility" in ($7, $8)
      and "asset"."deletedAt" is null
    )
  )
order by
  "asset"."updateId" asc

